-- New public versions and consent controls. Historical snapshots are immutable.
begin;
set local lock_timeout='5s';
set local statement_timeout='30s';

create table public.biometric_notice_versions (
 version text primary key, document_html text not null, source_sha256 text not null,
 wording_version text not null, consent_text text not null
);
create table public.dancer_biometric_consents (
 id uuid primary key, user_id uuid not null references public.app_users(id) on delete cascade,
 notice_version text not null references public.biometric_notice_versions(version),
 affirmative_action text not null default 'consent_before_capture' check(affirmative_action='consent_before_capture'),
 accepted_at timestamptz not null default clock_timestamp()
);
create index dancer_biometric_consents_account on public.dancer_biometric_consents(user_id,notice_version,accepted_at desc);
comment on table public.dancer_biometric_consents is 'Separate affirmative consent only. Never store outcomes, vendor references, raw files or biometric information here. Removed on account deletion; no six-year retention rule is adopted by this migration.';

create table public.request_terms_acceptances (
 id uuid primary key, flow text not null check(flow in ('guest_list','ride','table')),
 action text not null check(action in ('submit','cancel')),
 request_reference text not null check(length(request_reference) between 1 and 200),
 user_terms_version text not null references public.user_terms_versions(version),
 access_terms_version text references public.vip_access_terms_versions(version),
 consent_text text not null, accepted_at timestamptz not null default clock_timestamp(),
 check((flow='table' and access_terms_version is not null) or (flow<>'table' and access_terms_version is null and action='submit'))
);
comment on table public.request_terms_acceptances is 'Affirmative attempted action and versioned wording. Does not assert fulfillment or identify a natural person using a shared table. No name, contact details or browsing history.';
alter table public.biometric_notice_versions enable row level security;
alter table public.dancer_biometric_consents enable row level security;
alter table public.request_terms_acceptances enable row level security;
revoke all on public.biometric_notice_versions,public.dancer_biometric_consents,public.request_terms_acceptances from public,anon,authenticated,service_role;
grant select on public.biometric_notice_versions to service_role;
grant select,insert on public.dancer_biometric_consents,public.request_terms_acceptances to service_role;

update public.user_terms_versions set is_current=false where is_current;
insert into public.user_terms_versions(version,is_current,terms_href,source_sha256,content_sha256,document_html,consent_text,vip_consent_text) values ('2026-10-30',true,'/terms/user/2026-10-30','720ff3d31d918b4b6f26015ad2c341b365d0b491dc779c28b6afc63ce62adc75','640102e6168854244c584b05caeca07758988a9ae55258d28e957a3d041058ad',replace('<p>Last updated: October 30, 2026</p>
<p>MyDancr LLC, a Wyoming limited liability company (“MyDancr,” “we,” or “us”), provides online discovery, promotional profiles, club tools, and related request and notification features. These terms apply to your use of the features for which you accept them. You must be at least 18 and legally able to enter into this contract.</p>
<h2 id="user-terms-section-1">1 Acceptance and related documents</h2>
<p>Guest registration requires an affirmative acceptance box linked to these terms. VIP activation requires acceptance of these terms and the VIP &amp; Table Access Terms. Dancers separately accept the Dancer Agreement. Clubs separately approve the Club Agreement and their Order. The documents available through the legal index identify the terms for each relationship. Merely browsing, opening a table link, or viewing a notice does not establish affirmative acceptance.</p>
<p>You can accept these terms for a guest-list, ride, or table request without creating an account. To submit a request, you must affirmatively accept these terms and, for a table request, the VIP &amp; Table Access Terms through the linked acceptance box. Your affirmative acceptance applies to your use of that request feature. A table label or shared session does not establish another person’s acceptance. MyDancr records the accepted document versions, wording, action, time, and request or session reference.</p>
<p>A separately accepted Club Agreement and Order govern the club subscription and control conflicts about that relationship. The Dancer Agreement controls conflicts about dancer eligibility, media, visibility, licensing, and dancer-account disputes. VIP &amp; Table Access Terms control conflicts about those features. These terms otherwise govern your account and any request feature for which you accept them. The Privacy Policy explains information handling; acceptance of a contract does not replace separately required privacy or marketing consent.</p>
<h2 id="user-terms-section-2">2 What MyDancr provides</h2>
<p>Available features include dancer and club discovery, approved photos and short videos, MyDancr TV, club website embeds, follows and saved items, guest lists and admission passes, ride-request routing, table requests, and invitation-based VIP access. Features depend on location, account role, club setup, and eligibility. Not all features are available at every club.</p>
<p>MyDancr provides software and communications tools. Clubs operate their businesses and control their admissions, offers, personnel, transport arrangements, and services. MyDancr does not employ or book dancers, arrange unlawful services, collect payment for dancer services, or guarantee admission, attendance, availability, safety, or a particular result. Your arrangements with a club or dancer are separate.</p>
<h2 id="user-terms-section-3">3 Accounts and authorized access</h2>
<p>Provide accurate information, confirm your email when required, protect your credentials, and promptly report suspected compromise. You must use only your account and the access authorized for it. Club representatives must have authority for the actions they take. A staff login or invitation does not itself authorize a paid subscription, bind a dancer, or establish authority to change another person’s settings.</p>
<p>Guest accounts are free and provide available follows, saved items, and alert choices. Guest activity and follow lists are not public profiles. Dancer, club, staff, and VIP features require their respective approvals. Do not share private invitations, access codes, table links, or roster information beyond the use the club authorizes.</p>
<h2 id="user-terms-section-4">4 Profiles and visibility</h2>
<p>Working Now records a time-limited club check-in; it does not establish continuous presence, licensing, employment, or willingness to meet a guest. An eligible public off-shift profile may display “Not working now” without current or past club affiliation. Club affiliation appears publicly only during an eligible check-in and according to the dancer’s visibility choice.</p>
<p>Internal-only visibility permits access inside the checked-in club and by that club’s invited VIPs only while the dancer is checked in there. Another club’s invitation grants no access. Incognito excludes public and VIP viewing and guest requests. Authorized MyDancr and club personnel retain the operational access described in the Privacy Policy. Public embeds and MyDancr TV must respect the same public-visibility limits.</p>
<h2 id="user-terms-section-5">5 Requests admission and transport</h2>
<p>Table and VIP requests are routed to the club. Sending one does not create a booking or require a dancer to participate. “Seen” means staff acknowledged a table request. Club confirmation remains subject to availability and the dancer’s voluntary agreement. Contact the club about arrangements, prices, changes, and urgent matters. Statuses and alerts can be delayed or inaccurate.</p>
<p>People using the same table link can see and cancel that table’s open requests. Table access does not require an account or a named individual. Do not put sensitive information into request notes or assume a shared link creates a private conversation. The VIP &amp; Table Access Terms explain who can see your VIP information.</p>
<p>An admission pass is subject to its displayed terms, validity, arrival method, redemption rules, and the club’s lawful age, identification, capacity, dress, and house requirements. Club staff scan the patron’s QR pass. A guest-list entry does not itself promise free entry or admission. The club is responsible for its offers and valid redemptions.</p>
<p>MyDancr forwards pickup details to the selected club. A ride is confirmed only after the club accepts and contacts you. The club or its transport provider supplies and dispatches the driver and vehicle and is responsible for the transport. MyDancr does not operate a transport service. Use an appropriate emergency service in an emergency; request tools are not emergency channels.</p>
<h2 id="user-terms-section-6">6 Content and permitted use</h2>
<p>Use MyDancr only for lawful discovery, promotion, and authorized club functions. You must not use it for exploitation, trafficking, prostitution, unlawful sexual services, harassment, threats, discrimination, impersonation, fraud, or invasion of privacy. Do not request or post content involving minors, nonconsensual intimate imagery, nudity, actual or simulated sexual acts, or lascivious exhibition of the anus, genitals, or pubic area.</p>
<p>Do not submit another person’s identity documents or media. Dancer uploads must comply with the Dancer Agreement, show only the submitting adult dancer, and include only media and music the dancer has permission to use. Do not upload private records through profile fields, request notes, or ordinary support messages.</p>
<p>Do not scrape, crawl, harvest, bulk download, reidentify private users, bypass access or visibility restrictions, defeat moderation, introduce malware, misuse tags or QR passes, interfere with the service, or use accounts or content for unauthorized model training. Do not copy or rehost media, remove attribution or controls, or frame the service except through an authorized embed. Ordinary sharing through an available sharing tool remains subject to the recipient’s access rights.</p>
<h2 id="user-terms-section-7">7 Ownership and submissions</h2>
<p>MyDancr and its licensors retain their software, branding, and service materials. MyDancr gives you a limited, revocable, nontransferable permission to use the available features for their intended purpose, subject to these terms and applicable separate agreements. No ownership in the software or another user’s content transfers to you.</p>
<p>For request text, business information, or other material you submit outside dancer media, you grant MyDancr a nonexclusive license to host, format, transmit, and display it only as needed to provide the requested feature, maintain security, provide support, and comply with law. You must have the rights required for those uses. The license does not authorize unrelated advertising, general-purpose AI training, or public disclosure of private request information. It ends when the material is deleted except for restricted retention and processing described in the Privacy Policy. Dancer media and club branding have their separate licenses.</p>
<h2 id="user-terms-section-8">8 Moderation scores and support</h2>
<p>Dancer media must receive club approval and pass MyDancr moderation before publication. MyDancr may review activity, use automated screening, restrict material, and investigate reasonably suspected misuse. It may reject club-approved material. Approval does not guarantee safety, rights clearance, accuracy, or legality. MyDancr does not promise continuous review of every other interaction.</p>
<p>Available activity measures and rankings can use check-in and roster time, requests, customer interactions, and pass activity. Appearance summaries describe visible features such as hair color where that function is available. These outputs can be incomplete or wrong and do not verify identity, age, consent, availability, suitability, attendance, or revenue. The Privacy Policy describes their inputs and recipients. Ask <a href="mailto:support@mydancr.com">support@mydancr.com</a> for correction or review. Automated help does not replace a club’s confirmation or a response from MyDancr staff.</p>
<h2 id="user-terms-section-9">9 Reporting and enforcement</h2>
<p>Use the report control or <a href="mailto:support@mydancr.com">support@mydancr.com</a> for safety concerns. The Report Harmful Content notice in the legal index explains the intimate-image removal process, including access for nonusers. Copyright notices and counter-notices follow the DMCA Policy. MyDancr applies a repeat-infringer policy in appropriate circumstances. A copyright counter-notice does not override an independent safety restriction.</p>
<p>MyDancr may restrict access or content to investigate a suspected breach, unlawful activity, unauthorized access, or safety or security concern. It may terminate access for those reasons or another legitimate operational reason, subject to a controlling separate agreement. It will provide notice and a reasonable explanation when practical; disclosure may be withheld where prohibited or where it would compromise safety, security, or an investigation. Request review at <a href="mailto:support@mydancr.com">support@mydancr.com</a>.</p>
<h2 id="user-terms-section-10">10 Communications and third parties</h2>
<p>Account, security, legal, verification, and requested-service messages are distinct from optional alerts and marketing. Follow emails and offers/newsletters have separate choices. Following a club, submitting a request, or accepting terms does not itself subscribe you to marketing. Device push permission and club customer-list sharing are separate choices. See the Privacy Policy for controls and withdrawal methods.</p>
<p>Links, independent club services, and third-party tools have their own terms and privacy practices. An advertisement or link does not establish MyDancr’s endorsement or responsibility for the independent service. MyDancr must disclose any new use of personal information associated with direct advertising or a new integration as required by law.</p>
<h2 id="user-terms-section-11">11 Changes and account closure</h2>
<p>MyDancr may change or discontinue features. When practical, it will give reasonable notice of a change that substantially reduces an existing feature. Urgent legal, safety, security, or operational concerns can require earlier action. A general service change does not amend a signed Club Agreement or its payment and refund rights.</p>
<p>MyDancr may revise these terms prospectively. It will identify the new version and notify affected account holders of material changes, obtaining affirmative acceptance before applying those changes to continued use. Posting alone does not establish acceptance, and revisions do not change an existing dispute retroactively. You may decline and stop using the affected features.</p>
<p>You may stop using MyDancr or request closure through available controls or <a href="mailto:support@mydancr.com">support@mydancr.com</a>. Ordinary account access and display end on closure, subject to the separate agreements and restricted retention described in the Privacy Policy. Closing a login does not itself cancel a club subscription, erase accrued claims, or extend a content license or biometric destruction deadline.</p>
<h2 id="user-terms-section-12">12 Disclaimers and liability</h2>
<p>MyDancr provides the available service without a promise of uninterrupted operation, error-free information, a particular commercial result, or an independent participant’s conduct. To the extent permitted by law, MyDancr disclaims implied warranties of merchantability, fitness for a particular purpose, and noninfringement. These provisions do not eliminate an express obligation or a protection that applicable law does not allow to be excluded.</p>
<p>To the extent permitted by law, MyDancr and its suppliers are not liable for lost profits, lost business opportunities, loss of goodwill, losses resulting indirectly from inability to use the service, or punitive damages. Their total liability to you arising from these terms or your use of the service is limited to the greater of $100 and the amount you paid MyDancr for that use during the 12 months before the event giving rise to the claim. A separate agreement governs liability allocated to that relationship.</p>
<p>The exclusions and cap do not apply to fraud, willful misconduct, gross negligence, death or personal injury caused by negligence, or another liability or remedy that cannot lawfully be limited. Statutory privacy, consumer, and public injunctive rights remain available to the extent nonwaivable.</p>
<h2 id="user-terms-section-13">13 Third party claims caused by misuse</h2>
<p>To the extent permitted by law, you must indemnify MyDancr and its officers, employees, and agents against third-party claims, resulting damages, and reasonable defense costs caused by your unlawful use, your submission’s infringement of another person’s rights, or your material breach. This does not cover a claim to the extent caused by the protected person’s negligence, breach, fraud, or willful misconduct, or where law prohibits indemnification.</p>
<p>MyDancr must give reasonably prompt claim notice, allow you to control the covered defense using reasonably acceptable counsel, and provide reasonable cooperation at your expense. Delay in notice reduces your obligation only to the extent it prejudices the defense. You must not settle by admitting fault, imposing an obligation on a protected person, or leaving a protected person without an unconditional release unless that person consents. MyDancr may participate with its own counsel at its expense. Covered and uncovered portions must be allocated according to their cause.</p>
<h2 id="user-terms-section-14">14 Individual arbitration and dispute resolution</h2>
<p>Except for the matters identified below, you and MyDancr must resolve disputes arising from this document or your use of MyDancr by binding individual arbitration before one neutral arbitrator. The Federal Arbitration Act governs this arbitration provision. Arbitration replaces a court trial for the claims it covers and ordinarily provides more limited discovery and judicial review.</p>
<p>NAM (National Arbitration and Mediation) will administer the case under its Comprehensive Dispute Resolution Rules and Procedures in effect when the claim is filed, including mandatory supplemental procedures. NAM’s consumer fairness standards and consumer fee schedule apply when NAM classifies the dispute as a consumer matter. Applicable employment procedures and mandatory protections apply when required; this provision does not determine anyone’s worker classification. Rules, fees, and filing information are available from NAM or by calling 1-800-358-2550.</p>
<p>Before filing, the claimant must send a notice describing the dispute, the relevant account or request reference if available, and the relief sought. Send a notice to MyDancr at <a href="mailto:support@mydancr.com">support@mydancr.com</a> or MyDancr LLC, 30 N Gould St STE R, Sheridan, WY 82801, Attn Legal. MyDancr will use your account email or another address you provide. The parties must attempt resolution for 30 days after receipt. Applicable limitation periods are suspended during that period to the extent permitted by law. A party may file sooner when necessary to preserve a claim or obtain urgent relief.</p>
<p>Hearings will take place by video or telephone unless the parties agree otherwise or the arbitrator determines another format is required for a fair hearing. Any required in-person hearing must be reasonably convenient to the individual participant. The arbitrator may allow relevant discovery and award the relief available under applicable law and must issue a reasoned written decision.</p>
<p>Fees follow the applicable NAM schedule and law. MyDancr must pay the amounts assigned to the business and any additional amount required to prevent prohibitive costs from defeating access to arbitration. Each party bears its legal fees unless applicable law permits an award or a separate, enforceable indemnity covers a third-party claim. A good-faith challenge to this document or arbitration does not itself create a penalty or fee obligation.</p>
<p>Either party may bring an eligible individual claim in small-claims court. Either party may ask a court for temporary relief needed to preserve the status quo pending arbitration. Claims or remedies that cannot lawfully be subjected to predispute arbitration may proceed in court, including where the Ending Forced Arbitration of Sexual Assault and Sexual Harassment Act applies. Nothing prevents government reports or investigations or waives nonwaivable public injunctive relief.</p>
<p>Claims must proceed individually. Neither party may pursue a class, collective, or representative proceeding, or consolidate different claimants’ disputes, unless all affected parties expressly agree after the dispute arises. A court decides formation of the arbitration agreement, enforceability of this waiver, and other questions the law reserves to courts. The arbitrator decides the remaining arbitrable issues. If a claim or remedy cannot lawfully be subject to this waiver, that part will proceed in court and the remaining arbitrable claims will proceed in arbitration, subject to applicable law.</p>
<p>If NAM declines to administer and the parties do not agree on a substitute no later than 30 days afterward, either party may proceed in a court with jurisdiction. This fallback does not excuse required fees or eliminate remedies for nonpayment. Applicable law supplies claim deadlines; this document does not shorten them.</p>
<p>You may opt out of this arbitration provision by emailing <a href="mailto:support@mydancr.com">support@mydancr.com</a> no later than 30 days after first accepting it. Include your name, account email if any, and an unambiguous statement that you opt out of arbitration. If you accepted without an account, provide a request reference or other details that let us locate your acceptance. Opting out does not affect other terms or a separate arbitration agreement you validly accepted.</p>
<h2 id="user-terms-section-15">15 Governing law and remaining terms</h2>
<p>Wyoming law governs these terms, subject to the Federal Arbitration Act and mandatory law. For proceedings permitted in court, you and MyDancr consent to the exclusive jurisdiction and venue of the state and federal courts located in Wyoming, except eligible small-claims cases and a forum required by nonwaivable law. This selection does not deprive a consumer of mandatory protections.</p>
<p>These terms and any separate documents validly accepted for your account or use of a feature form the agreement between you and MyDancr. Section 1 resolves conflicts between those documents. You must not assign your rights without MyDancr’s written consent. MyDancr may assign to a successor that assumes its obligations in a merger, reorganization, or transfer of the service, subject to privacy law and nonwaivable rights. An unauthorized assignment is ineffective.</p>
<p>If a provision is unenforceable, the remaining provisions continue to the extent they can operate lawfully, subject to the arbitration rules above. Failure to enforce a provision on one occasion does not waive it later. Accrued claims, ownership, licenses for their stated duration, lawful restricted retention, applicable indemnity, liability limits, and dispute provisions continue only as needed to give them effect.</p>
<h2 id="user-terms-section-16">16 Contact</h2>
<p>Email <a href="mailto:support@mydancr.com">support@mydancr.com</a> or write to MyDancr LLC, 30 N Gould St STE R, Sheridan, WY 82801. Dispute notices follow section 14.</p>',E'\r\n',E'\n'),'I’m 18 or older and agree to the User Terms.','I’m 18 or older and agree to the User Terms and VIP & Table Access Terms.');
update public.dancer_agreement_versions set is_current=false where is_current;
insert into public.dancer_agreement_versions(version,is_current,source_sha256,content_sha256,document_html,consent_text) values ('2026-10-30',true,'f656ff4f65701d322752b17c01c5aec921eda82bb5ef6a10164b6ef60288d5cb','8fa324e6824d0113dc39e52e657721ff0dab802f0008955ad9adbaf85c23c6ce',replace('<p>Last updated: October 30, 2026</p>
<p>This document governs your dancer account with MyDancr LLC, a Wyoming limited liability company (“MyDancr,” “we,” or “us”). It covers your promotional profile and access to MyDancr’s software. It does not engage you to perform work for MyDancr or determine your separate relationship with a club.</p>
<h2 id="dancer-agreement-section-1">1 Acceptance and relationship</h2>
<p>You must affirmatively accept this agreement before continuing to identity and age verification. Accepting this agreement does not give consent to biometric processing or marketing. The User Terms and feature notices apply where separately accepted and relevant. This agreement controls conflicts about your dancer eligibility, media, visibility, license, and account disputes. The Privacy Policy and the Dancer Verification and Biometric Privacy Notice explain personal-information handling.</p>
<p>Your account is free. MyDancr does not employ, schedule, supervise, book, or pay you for performances and does not collect payment for dancer services. Nothing here waives a worker right or changes a classification determined by law. Club admission, licensing, compensation, and work arrangements remain separate.</p>
<h2 id="dancer-agreement-section-2">2 Eligibility and verification</h2>
<p>You must be at least 18, have legal capacity, operate your own account, and provide accurate information. You must hold the licenses, permits, work authorization, and club qualifications required for your activities. Your MyDancr status does not replace those requirements. You must not use someone else’s identity, documents, likeness, account, or stage identity to mislead anyone.</p>
<p>Before your account can go live, complete identity and age verification through UAB “Ondato” using your government-issued ID and live selfie. Ondato checks your ID, compares your face with the ID, and checks that the selfie shows a real person. These checks involve facial biometric processing. Review and affirmatively accept the separate verification notice before capture. Declining prevents dancer activation. Verification failures and uncertain results can require review or prevent activation.</p>
<p>Authorized MyDancr personnel can access verification records Ondato makes available for verification, related support, security, and legal purposes. These are not public profile records. MyDancr’s limited retained verification record and Ondato’s 30-day deletion setting are described in the verification notice and Privacy Policy. Account acceptance does not authorize unrelated profiling, advertising, or retention of raw verification files.</p>
<h2 id="dancer-agreement-section-3">3 Activation club affiliation and check-ins</h2>
<p>To activate your profile, create an account and submit media for club approval and MyDancr moderation. The approved profile stays private until you complete Ondato verification and intentionally tap the club’s official dressing-room NFC tag in person, with the tap validated by MyDancr. Completing only some steps does not authorize publication. Bios are not supported.</p>
<p>A validated intentional tap establishes club affiliation automatically; no additional approval of that affiliation by a club representative is required. An authorized club user may remove the affiliation. You may use club-specific scheduling and Working Now only while your affiliation is active and the feature’s conditions are met.</p>
<p>Working Now lasts for the period shown when you check in, followed by any displayed cooldown. Repeated taps do not extend that period unless the check-in screen expressly says they will. End or correct an inaccurate status through available controls and report a malfunction. MyDancr records the club, time, tag reference, and technical information needed to validate the event and prevent fraud. The NFC process does not use continuous or background location tracking or a geofence.</p>
<p>Do not copy, relocate, emulate, relay, alter, or misuse a tag; automate or simulate a tap; have someone check in for you; or falsify presence, pass, or request records. A validated tap and a status badge do not establish continuing presence, a job relationship, availability, or consent to a guest’s request.</p>
<h2 id="dancer-agreement-section-4">4 Visibility and public distribution</h2>
<p>Your visibility choice applies to approved media, stage name, city, supported profile fields, schedules, and Working Now information. Public profiles can be viewed or copied by others. An eligible public off-shift profile may show “Not working now” without current or past club affiliation. Current affiliation is displayed publicly only during an eligible check-in and according to your selection.</p>
<p>Internal-only visibility means your profile is available inside the club where you are checked in and to that club’s invited VIPs while you are checked in there, and is hidden from public discovery. Another club’s VIP invitation does not provide access. Incognito hides your profile from public users and invited VIPs and blocks their requests. It does not eliminate authorized administrative, moderation, safety, or legal access.</p>
<p>MyDancr TV and authorized public club embeds must respect the public-visibility limits. Internal-only and Incognito content must not be publicly embedded. Visibility changes restrict later authorized display but cannot recall copies independently retained by third parties. Report a visibility error promptly to <a href="mailto:support@mydancr.com">support@mydancr.com</a>.</p>
<h2 id="dancer-agreement-section-5">5 Permitted media and rights</h2>
<p>Use only the available profile fields and submit promotional photos and short videos in the supported formats. You must be the only depicted person, including in backgrounds and reflections, and must have been at least 18 when each item was created. You must own or have permission for the images, footage, music, performance, likeness, and other material used. Keep records of those rights and provide reasonable evidence when requested.</p>
<p>Covered bikinis, lingerie, and thongs are permitted. Nipples and private parts must remain covered. Do not submit nudity, actual or simulated sexual acts, or lascivious exhibition of the anus, genitals, or pubic area. Do not submit minors, nonconsensual intimate imagery or deceptive sexual deepfakes, other depicted people, sexual solicitation, trafficking or exploitation, drugs, violence, threats, hate, or unlawful material.</p>
<p>Do not place logos, watermarks, contact information, social or payment handles, QR codes, or similar directions in media. A supported separate profile link does not authorize embedding such information in an image or video. Follow the displayed format, length, and size limits. MyDancr may change technical limits for future submissions. Those changes do not permit content prohibited by this agreement.</p>
<h2 id="dancer-agreement-section-6">6 Review of media decisions</h2>
<p>Each item must receive club approval and pass MyDancr moderation before publication. Automated screening assists review and does not establish legality or rights ownership. Club approval does not override MyDancr’s rules. An item can be rejected, restricted, or removed; approved material may remain visible while an update is pending.</p>
<p>MyDancr may request further rights or eligibility evidence and restrict the affected item while the issue is reviewed. It will give a reason for an adverse decision when practical and lawful. Request review or correction at <a href="mailto:support@mydancr.com">support@mydancr.com</a>, identifying the item and relevant facts. An appeal does not guarantee publication or prevent urgent safety action.</p>
<h2 id="dancer-agreement-section-7">7 Your license to MyDancr</h2>
<p>You retain ownership of your submitted media and supported profile information (“Dancer Content”). For the period and purposes below, you grant MyDancr a nonexclusive, worldwide, royalty-free license to host, copy, technically format, transmit, and display Dancer Content to provide your authorized profile and the features you select. MyDancr may permit its service providers to perform those functions under the same limits.</p>
<p>The license includes eligible display through MyDancr TV and approved embeds on club-controlled websites. It is limited by your visibility choices and does not authorize unrelated advertising campaigns, sale of your content, unrestricted sublicensing, or general-purpose AI training. A separate advertising campaign requires separate permission. Technical cropping, resizing, compression, and transcoding must not materially misrepresent you.</p>
<p>The license also permits use of the stage name, image, voice, and other identifying elements in Dancer Content for those authorized purposes. It does not cover your verification materials, legal identity, another person’s likeness, or an unrelated endorsement. You must not submit material whose authorized use requires an undisclosed third-party payment.</p>
<p>The license ends for an item when it is deleted or the authorized display ends, except restricted copies and processing needed for the limited retention, security, disputes, and legal purposes described in the Privacy Policy. Those exceptions do not permit continued ordinary promotion. MyDancr retains its software and branding; you receive only permission to use the authorized features.</p>
<h2 id="dancer-agreement-section-8">8 Requests and voluntary participation</h2>
<p>Table and VIP requests are routed to club personnel. The selected dancer may receive anonymous VIP visit details. A request, status badge, staff acknowledgment, or club confirmation does not require you to meet anyone, perform, or accept an engagement. Participation requires your voluntary agreement and coordination with the club. Contact the club about arrangements, pricing, safety, and changes.</p>
<p>MyDancr does not guarantee the identity, conduct, or suitability of a guest. Do not use the service for unlawful sexual services, coercion, retaliation, exploitation, or disclosure of private guest information. Report threats and safety concerns; use emergency services for an immediate emergency.</p>
<h2 id="dancer-agreement-section-9">9 Automation activity measures and privacy</h2>
<p>MyDancr uses submitted profile media, sampled video frames, extracted audio, and related transcripts or captions for moderation as described in the Privacy Policy. This is separate from Ondato verification. Do not place verification documents or selfies in profile media or ordinary messages.</p>
<p>Available scores and rankings use recorded roster and check-in time, check-in and checkout behavior, table requests, VIP selections and returning requesters, profile interactions, and pass claims and redemptions. Your club can see its activity measures and your results. A visibility choice does not erase lawful historical operational records. Results can be affected by missing data or a short activity history.</p>
<p>Available hair-color analytics describe visible hair in approved main photos and group activity by the photo recorded when the activity occurred. Earlier activity can stay linked to the earlier photo. These measures do not establish revenue, attendance, safety, qualifications, or what caused a result. Ask <a href="mailto:support@mydancr.com">support@mydancr.com</a> to review an inaccurate result. Verification files and facial biometric data are not inputs to these features.</p>
<h2 id="dancer-agreement-section-10">10 Conduct security and enforcement</h2>
<p>Protect your account, use authorized access only, and promptly report compromise. Do not scrape, harvest, bulk copy, reidentify users, bypass controls, tamper with tags or passes, introduce malware, or use private records or other users’ media for unauthorized model training. Do not harass, impersonate, threaten, or retaliate against anyone.</p>
<p>MyDancr may restrict content or access while investigating suspected misuse, an eligibility issue, or a safety, security, or legal concern. It may terminate for a material breach, ineligibility, unlawful conduct, or another legitimate operational reason. It will provide notice and a reasonable explanation when practical; disclosure may be withheld to protect safety, an investigation, security, or legal duties. Seek review through <a href="mailto:support@mydancr.com">support@mydancr.com</a>.</p>
<h2 id="dancer-agreement-section-11">11 Reporting rights and account closure</h2>
<p>The DMCA Policy explains copyright notices and counter-notices. The Report Harmful Content notice in the legal index provides a separate removal process for intimate imagery, including requests by nonusers and depicted people. Do not forward suspected child sexual abuse material through ordinary email or messages.</p>
<p>You may disable your account or request deletion through available controls or <a href="mailto:support@mydancr.com">support@mydancr.com</a>. Closure ends ordinary display and access; it does not change your independent club relationship, erase accrued claims, or authorize an extension of content licenses or biometric deadlines. Restricted retention follows the Privacy Policy.</p>
<h2 id="dancer-agreement-section-12">12 Changes</h2>
<p>MyDancr may revise this agreement prospectively. For a material change it will identify the new version, notify you through the account or email, and require affirmative acceptance before applying it to continued use. Posting alone is insufficient, and revisions do not change an existing dispute retroactively. You may decline and stop using the affected service.</p>
<h2 id="dancer-agreement-section-13">13 Disclaimers liability and third party claims</h2>
<p>MyDancr does not promise continuous access, accurate automated outputs, bookings, income, attendance, or any independent participant’s conduct. To the extent permitted by law it disclaims implied warranties of merchantability, fitness for a particular purpose, and noninfringement. No disclaimer eliminates an express obligation or nonwaivable protection.</p>
<p>To the extent permitted by law, MyDancr and its providers are not liable for lost profits, lost business opportunities, loss of goodwill, losses resulting indirectly from inability to use the service, or punitive damages. Their aggregate liability to you arising from this agreement or the dancer service is limited to the greater of $100 and the amount you paid MyDancr for that service in the 12 months before the event. These exclusions and the cap do not apply to fraud, willful misconduct, gross negligence, death or personal injury caused by negligence, or a nonwaivable liability or remedy.</p>
<p>To the extent permitted by law, you must indemnify MyDancr and its officers, employees, and agents against third-party claims, resulting damages, and reasonable defense costs caused by unlawful account use, Dancer Content’s violation of another person’s rights, or your material breach. Your obligation does not cover the protected person’s own negligence, breach, fraud, or willful misconduct. MyDancr must give reasonably prompt claim notice, permit your defense with reasonably acceptable counsel, and provide reasonable cooperation at your expense. A delay in notice reduces your obligation only to the extent it prejudices the defense. A settlement admitting fault, imposing an obligation, or failing to provide an unconditional release requires the affected person’s consent. Covered and uncovered portions of a claim must be allocated according to their cause.</p>
<h2 id="dancer-agreement-section-14">14 Individual arbitration</h2>
<p>Except for the matters identified below, you and MyDancr must resolve disputes arising from this document or your use of MyDancr by binding individual arbitration before one neutral arbitrator. The Federal Arbitration Act governs this arbitration provision. Arbitration replaces a court trial for the claims it covers and ordinarily provides more limited discovery and judicial review.</p>
<p>NAM (National Arbitration and Mediation) will administer the case under its Comprehensive Dispute Resolution Rules and Procedures in effect when the claim is filed, including mandatory supplemental procedures. NAM’s consumer fairness standards and consumer fee schedule apply when NAM classifies the dispute as a consumer matter. Applicable employment procedures and mandatory protections apply when required; this provision does not determine anyone’s worker classification. Rules, fees, and filing information are available from NAM or by calling 1-800-358-2550.</p>
<p>Before filing, the claimant must send a notice describing the dispute, the relevant account, and the relief sought. Send a notice to MyDancr at <a href="mailto:support@mydancr.com">support@mydancr.com</a> or MyDancr LLC, 30 N Gould St STE R, Sheridan, WY 82801, Attn Legal. MyDancr will use your account email or another address you provide. The parties must attempt resolution for 30 days after receipt. Applicable limitation periods are suspended during that period to the extent permitted by law. A party may file sooner when necessary to preserve a claim or obtain urgent relief.</p>
<p>Hearings will take place by video or telephone unless the parties agree otherwise or the arbitrator determines another format is required for a fair hearing. Any required in-person hearing must be reasonably convenient to the individual participant. The arbitrator may allow relevant discovery and award the relief available under applicable law and must issue a reasoned written decision.</p>
<p>Fees follow the applicable NAM schedule and law. MyDancr must pay the amounts assigned to the business and any additional amount required to prevent prohibitive costs from defeating access to arbitration. Each party bears its legal fees unless applicable law permits an award or a separate, enforceable indemnity covers a third-party claim. A good-faith challenge to this document or arbitration does not itself create a penalty or fee obligation.</p>
<p>Either party may bring an eligible individual claim in small-claims court. Either party may ask a court for temporary relief needed to preserve the status quo pending arbitration. Claims or remedies that cannot lawfully be subjected to predispute arbitration may proceed in court, including where the Ending Forced Arbitration of Sexual Assault and Sexual Harassment Act applies. Nothing prevents government reports or investigations or waives nonwaivable public injunctive relief.</p>
<p>Claims must proceed individually. Neither party may pursue a class, collective, or representative proceeding, or consolidate different claimants’ disputes, unless all affected parties expressly agree after the dispute arises. A court decides formation of the arbitration agreement, enforceability of this waiver, and other questions the law reserves to courts. The arbitrator decides the remaining arbitrable issues. If a claim or remedy cannot lawfully be subject to this waiver, that part will proceed in court and the remaining arbitrable claims will proceed in arbitration, subject to applicable law.</p>
<p>If NAM declines to administer and the parties do not agree on a substitute no later than 30 days afterward, either party may proceed in a court with jurisdiction. This fallback does not excuse required fees or eliminate remedies for nonpayment. Applicable law supplies claim deadlines; this document does not shorten them.</p>
<p>You may opt out of this arbitration provision by emailing <a href="mailto:support@mydancr.com">support@mydancr.com</a> no later than 30 days after first accepting it. Include your name, account email, and an unambiguous statement that you opt out of arbitration. Opting out does not affect other terms or a separate arbitration agreement you validly accepted.</p>
<h2 id="dancer-agreement-section-15">15 Governing law and other terms</h2>
<p>Wyoming law governs, subject to the Federal Arbitration Act and mandatory law. For proceedings permitted in court, you and MyDancr consent to the exclusive jurisdiction and venue of the state and federal courts located in Wyoming, except eligible small-claims cases or a forum required by nonwaivable law. Consumer and worker protections that cannot lawfully be waived remain available.</p>
<p>This agreement and other documents validly accepted for the relevant feature govern your dancer-account relationship. Section 1 resolves conflicts. You must not transfer your account or rights without MyDancr’s written consent. MyDancr may assign to a successor that assumes its duties in a merger, reorganization, or service transfer, subject to privacy law and nonwaivable rights. Invalid provisions are severable to the extent the remaining provisions can operate lawfully, subject to section 14. Failure to enforce a provision on one occasion does not waive it later.</p>
<p>Accrued claims, ownership, licenses only for their stated duration, lawful restricted retention, indemnity for covered prior conduct, liability limits, and dispute provisions continue only as needed to give them effect.</p>
<h2 id="dancer-agreement-section-16">16 Contact</h2>
<p>Email <a href="mailto:support@mydancr.com">support@mydancr.com</a> or write to MyDancr LLC, 30 N Gould St STE R, Sheridan, WY 82801.</p>',E'\r\n',E'\n'),'I’m 18 or older and agree to the Dancer Agreement.');
insert into public.vip_access_terms_versions(version,terms_href,title,document_text,notice_text,consent_text,privacy_href) values ('2026-10-30','/terms/vip-table/2026-10-30','VIP & Table Access Terms',replace('<p>Last updated: October 30, 2026</p>
<p>MyDancr LLC provides private VIP and club table-request tools. You must be at least 18 and satisfy the club’s separate admission requirements. An account, link, invitation, roster listing, or request does not verify admission eligibility or guarantee entry.</p>
<h2 id="vip-table-section-1">1 Acceptance and authorization</h2>
<p>VIP access begins through a club invitation and account activation. The activation screen requires affirmative acceptance of the User Terms and these terms, with links to both. The legal index provides current versions and the Privacy Policy. MyDancr records the accepting account, invitation, club, document versions, acceptance wording, and server time. An invitation authorizes only the club access it identifies and may be revoked.</p>
<p>Once accepted, these terms supplement the User Terms for your VIP or table use and control conflicts about the VIP or table feature. The User Terms provide the other applicable account, conduct, liability, and NAM dispute provisions. Acceptance of these documents does not supply marketing consent or another separately required consent.</p>
<p>Deleting your shared login ends VIP access at all venues and the associated customer-dashboard access. Contact the club if you want to end only that club’s VIP membership. The Privacy Policy explains restricted retention after closure.</p>
<h2 id="vip-table-section-2">2 Dancer selection and requests</h2>
<p>The VIP roster offers eligible dancers working now at the invited club. Internal-only visibility can include that club’s invited VIPs while the dancer is checked in there. An invitation from another club grants no access. Incognito excludes VIP viewing and requests. Rosters can change, and a status does not establish continuing presence or willingness to meet a guest.</p>
<p>Choose the available dancers, date, and time; times follow the club’s displayed time zone. Sending a request routes it to the club and does not create a booking. Club confirmation remains subject to availability and each dancer’s voluntary agreement. It does not require a dancer to participate. Contact club staff about arrangements, prices, changes, withdrawal, or an urgent matter. Use available request controls where offered; a change is not confirmed until the club responds.</p>
<p>MyDancr supplies communication tools. It does not operate the club, employ or book dancers, collect payment for dancer services, arrange unlawful services, or promise admission, attendance, service, or safety. Requests and notifications can be delayed or inaccurate. For an emergency, use appropriate emergency services.</p>
<h2 id="vip-table-section-3">3 VIP information visibility</h2>
<p>The invited club’s owners and managers can see your VIP membership, supplied name, private club nickname, requests, notes, and responses. You can see your own requests and responses. Selected dancers can receive anonymous visit details. MyDancr can access relevant information to operate, support, secure, and lawfully administer the feature. Requests are not direct private messages to dancers. Do not include sensitive personal information in notes.</p>
<h2 id="vip-table-section-4">4 Shared table notice</h2>
<p>A table QR link can open an internal roster without a guest account. Anyone using the same table link can see and cancel that table’s open requests. The link identifies the table rather than a private individual guest. Do not assume a request or cancellation is visible only to you. The club may rotate or revoke links and apply access controls.</p>
<p>Table requests go to authorized club staff with the table label and status. “Seen” means staff acknowledged the request; it does not mean a dancer agreed or a service occurred. Availability and voluntary agreement still apply. No guest name or email is required for this feature, although technical activity is processed as described in the Privacy Policy.</p>
<p>Before submitting, changing, or canceling a table request, you must affirmatively accept these terms and the User Terms through the linked acceptance box. You can accept without creating an account. Another guest’s acceptance or a shared table label does not establish that you accepted. MyDancr records the accepted versions, wording, affirmative action, time, and request or session reference. Viewing a table roster or opening its notice alone does not constitute acceptance.</p>
<h2 id="vip-table-section-5">5 Conduct and choices</h2>
<p>Use accounts and private links only as authorized. Do not redistribute roster content or invitations, scrape or rehost profiles, impersonate others, bypass visibility controls, harass anyone, or request unlawful services. Interactions must be lawful and consensual. The club or MyDancr may revoke access for misuse, ineligibility, or safety and security needs, subject to any applicable agreement and law.</p>
<p>VIP activation, table access, and requests do not subscribe you to marketing or add you to a club customer list. Those choices are separate. Essential request and account messages are distinct from optional promotional communications. See the Privacy Policy for preferences, withdrawal, and retention.</p>
<p>Rights and duties that cannot lawfully be limited remain unaffected. Contact <a href="mailto:support@mydancr.com">support@mydancr.com</a> for MyDancr questions and club staff for admission, requests, and arrangements.</p>',E'\r\n',E'\n'),'Your club’s owners and managers can see your name and VIP requests. Selected dancers can receive anonymous visit details. Requests depend on dancer availability and voluntary agreement; sending one does not confirm a booking. MyDancr records your acceptance, including both terms versions and time. This does not sign you up for marketing.','I’m 18 or older and agree to the User Terms and VIP & Table Access Terms.','/privacy');
insert into public.biometric_notice_versions(version,document_html,source_sha256,wording_version,consent_text) values ('2026-10-30',replace('<p>Last updated: October 30, 2026</p>
<p>MyDancr LLC uses UAB “Ondato” to verify a dancer’s identity and confirm age 18 or older before activation. This notice explains the processing and MyDancr’s public retention and destruction policy. Read it before deciding whether to proceed. Contract acceptance and biometric consent are separate.</p>
<h2 id="dancer-verification-section-1">1 What is processed and why</h2>
<p>Ondato captures your government-issued ID and a live selfie, including images or video for liveness checks. It reads document information and processes facial biometric information to compare your face with the ID and check for a real person. The process can approve, reject, or refer a result for review. MyDancr uses this information for identity and age eligibility, related support, security, and legal purposes.</p>
<p>Authorized MyDancr personnel can access the verification records Ondato makes available during the applicable retention period for those purposes. Your ID, verification selfie or video, and legal identity are not public dancer profile or club-roster material. Verification information is not used for advertising, engagement rankings, appearance summaries, or general-purpose AI training and is not sold.</p>
<h2 id="dancer-verification-section-2">2 Ondato records</h2>
<p>Ondato’s configured retention period for identifiable verification records is 30 days. This covers ID and selfie images or video and extracted document data. Ondato has confirmed that it does not retain derived facial templates or measurements or backup copies of deleted records. Limited transaction references, timestamps, and statuses can remain; MyDancr treats them as personal information when linkable to you.</p>
<p>MyDancr and clubs must not use their access to keep independent copies of raw verification records. MyDancr’s own retained result record is limited as described below. Keeping an account active does not extend Ondato’s retention period.</p>
<h2 id="dancer-verification-section-3">3 MyDancr retention and permanent destruction</h2>
<p>MyDancr limits its retained verification record to the account reference, verification date, identity and age-18-or-older result, Ondato transaction reference, consent time, and notice version. It keeps that limited record for the active account and no longer than 3 years after closure, deleting sooner when no longer needed or required by law. It excludes ID and selfie copies, verification video, full birth date, document number, and detailed face-match data. A specific lawful preservation requirement can apply to a specified limited record.</p>
<p>MyDancr keeps a separate consent record containing only the account reference, notice and wording version, affirmative action, and time. It keeps that evidence only as reasonably needed to demonstrate your choice and handle related claims or legal duties, then deletes it. This consent record excludes verification files, biometric information, verification outcomes, and vendor transaction references. It does not authorize further verification processing or extend any verification-file or biometric destruction period.</p>
<p>Any biometric identifiers or biometric information must be permanently destroyed when the initial verification purpose is satisfied or no later than 3 years after your last interaction with MyDancr, whichever occurs first. A shorter applicable legal period or the vendor’s shorter setting controls. This rule does not authorize retaining derived templates or extend the 30-day vendor setting. A biometric deadline may be altered only by a legally applicable exception, such as a valid court warrant or subpoena where controlling law permits it; an internal hold alone does not extend the deadline.</p>
<p>MyDancr must restrict access, protect the information with reasonable safeguards appropriate to its sensitivity, and limit disclosure to the verification process, a disclosure you authorize, or another disclosure permitted by applicable law. MyDancr does not trade or profit from biometric information.</p>
<h2 id="dancer-verification-section-4">4 Your choice and requests</h2>
<p>You may decline or stop before capture, but an unverified dancer account cannot be activated. To withdraw consent or request access, correction, or deletion, contact <a href="mailto:support@mydancr.com">support@mydancr.com</a>. Withdrawal ends further processing that depends on consent, subject to lawful limited-record retention or a specific mandatory duty. Withdrawing or giving consent does not waive your privacy or biometric rights. The Privacy Policy explains related rights and account practices.</p>
<h2 id="dancer-verification-section-5">5 Separate consent before capture</h2>
<p>☐ I consent to MyDancr LLC and UAB “Ondato” collecting, processing, and disclosing my ID, live selfie images or video, and facial biometric information for identity and age verification and related support, security, and legal purposes described in this notice. I understand the retention and destruction rules and that declining prevents activation of my dancer account.</p>
<p>Continue to verification</p>
<p>You give the consent above by a separate affirmative choice before capture. Opening this notice or accepting the Dancer Agreement does not supply that consent. Ondato may also present its own notice and consent. Contact <a href="mailto:support@mydancr.com">support@mydancr.com</a> or MyDancr LLC, 30 N Gould St STE R, Sheridan, WY 82801 with questions.</p>',E'\r\n',E'\n'),'e6a4a6703c7b09146dc8ba7b65b36bbeef699fa237c003806a39ed661c11010a','2026-10-30','I consent to MyDancr LLC and UAB “Ondato” collecting, processing, and disclosing my ID, live selfie images or video, and facial biometric information for identity and age verification and related support, security, and legal purposes described in this notice. I understand the retention and destruction rules and that declining prevents activation of my dancer account.');


create function public.record_request_terms_acceptance(
 p_id uuid,p_flow text,p_action text,p_reference text,p_user_version text,p_access_version text,p_accepted boolean
) returns jsonb language plpgsql security invoker set search_path='' as $function$
declare v public.request_terms_acceptances; wording text;
begin
 if p_id is null or p_accepted is distinct from true or p_flow not in ('guest_list','ride','table') or p_flow is null
   or p_action not in ('submit','cancel') or p_action is null or p_reference is null or length(p_reference) not between 1 and 200
   or (p_flow<>'table' and (p_action<>'submit' or p_access_version is not null))
   or (p_flow='table' and p_access_version is distinct from '2026-10-30') then
   raise exception 'REQUEST_TERMS_REQUIRED' using errcode='22023';
 end if;
 select case when p_flow='table' then vip_consent_text else consent_text end into wording
 from public.user_terms_versions where version=p_user_version and is_current;
 if not found then raise exception 'CURRENT_USER_TERMS_REQUIRED' using errcode='22023'; end if;
 insert into public.request_terms_acceptances(id,flow,action,request_reference,user_terms_version,access_terms_version,consent_text)
 values(p_id,p_flow,p_action,p_reference,p_user_version,p_access_version,wording) on conflict(id) do nothing;
 select * into strict v from public.request_terms_acceptances where id=p_id;
 if v.flow<>p_flow or v.action<>p_action or v.request_reference<>p_reference or v.user_terms_version<>p_user_version
   or v.access_terms_version is distinct from p_access_version then
   raise exception 'ACCEPTANCE_REFERENCE_CONFLICT' using errcode='22023';
 end if;
 return jsonb_build_object('id',v.id,'acceptedAt',v.accepted_at);
end;
$function$;

create function public.record_dancer_biometric_consent(p_id uuid,p_user uuid,p_version text,p_accepted boolean)
returns jsonb language plpgsql security invoker set search_path='' as $function$
declare v public.dancer_biometric_consents;
begin
 if p_id is null or p_accepted is distinct from true or p_version is distinct from '2026-10-30'
 or not exists(select 1 from public.app_users where id=p_user and role='dancer' and account_state='active')
 or not exists(select 1 from public.dancer_agreement_acceptances a join public.dancer_agreement_versions d on d.version=a.version
   where a.user_id=p_user and d.is_current) then
   raise exception 'BIOMETRIC_CONSENT_REQUIRED' using errcode='22023';
 end if;
 insert into public.dancer_biometric_consents(id,user_id,notice_version) values(p_id,p_user,p_version) on conflict(id) do nothing;
 select * into strict v from public.dancer_biometric_consents where id=p_id;
 if v.user_id<>p_user or v.notice_version<>p_version then raise exception 'CONSENT_REFERENCE_CONFLICT' using errcode='22023'; end if;
 return jsonb_build_object('id',v.id,'acceptedAt',v.accepted_at);
end;
$function$;

alter table public.dancer_age_verifications add column consent_at timestamptz,
 add column notice_version text references public.biometric_notice_versions(version);

create or replace function public.reserve_dancer_age_verification(p_user_id uuid,p_integration_id uuid)
returns jsonb language plpgsql security definer set search_path=public,pg_temp as $function$
declare v public.dancer_age_verifications; v_now timestamptz:=clock_timestamp(); c public.dancer_biometric_consents;
begin
 if p_integration_id is null or not exists(select 1 from public.app_users where id=p_user_id and role='dancer' and account_state='active') then
   raise exception using errcode='42501',message='Active dancer account and integration required.';
 end if;
 if not exists(select 1 from public.dancer_profiles where user_id=p_user_id and status::text in ('pending_review','approved') and disabled_at is null) then
   raise exception using errcode='42501',message='AGE_PROFILE_SETUP_REQUIRED';
 end if;
 select * into c from public.dancer_biometric_consents where user_id=p_user_id and notice_version='2026-10-30' order by accepted_at desc limit 1;
 if not found then raise exception using errcode='42501',message='BIOMETRIC_CONSENT_REQUIRED'; end if;
 insert into public.dancer_age_verifications(user_id,provider,provider_integration_id,consent_at,notice_version)
 values(p_user_id,'ondato',p_integration_id::text,c.accepted_at,c.notice_version) on conflict do nothing;
 select * into v from public.dancer_age_verifications where user_id=p_user_id for update;
 update public.dancer_age_verifications set consent_at=c.accepted_at,notice_version=c.notice_version where user_id=p_user_id returning * into v;
 if v.provider='ondato' and v.provider_integration_id=p_integration_id::text
 and (v.status in ('verified','in_review') or (v.status in ('creating','pending') and v.expires_at>v_now)) then
   return to_jsonb(v)||jsonb_build_object('reserved',false);
 end if;
 if v.attempt_window_at<=v_now-interval '24 hours' then v.attempt_count:=0;v.attempt_window_at:=v_now;end if;
 if v.attempt_count>=3 then raise exception using errcode='P0001',message='AGE_VERIFICATION_RETRY_LIMIT';end if;
 update public.dancer_age_verifications set attempt_id=gen_random_uuid(),session_id=null,provider='ondato',provider_integration_id=p_integration_id::text,
 status='creating',verification_url=null,created_at=v_now,expires_at=v_now+interval '90 seconds',checked_at=null,verified_at=null,
 attempt_window_at=v.attempt_window_at,attempt_count=v.attempt_count+1 where user_id=p_user_id returning * into v;
 return to_jsonb(v)||jsonb_build_object('reserved',true);
end;
$function$;

create or replace function public.vip_accept_invitation_with_user_terms(
 p_actor uuid,p_digest text,p_name text,p_version text,p_accepted boolean,p_user_terms_version text,p_user_terms_accepted boolean
) returns uuid language plpgsql security definer set search_path='' as $function$
declare v_venue uuid;v_invitation uuid;v_consent text;
begin
 if p_accepted is distinct from true or p_version is distinct from '2026-10-30' or p_user_terms_accepted is distinct from true then
   raise exception 'VIP_TERMS_REQUIRED' using errcode='22023';end if;
 select vip_consent_text into v_consent from public.user_terms_versions where version=p_user_terms_version and is_current;
 if not found then raise exception 'USER_TERMS_REQUIRED' using errcode='22023';end if;
 v_venue:=public.vip_accept_invitation(p_actor,p_digest,p_name);
 select id into strict v_invitation from public.venue_vip_invitations where token_digest=p_digest and accepted_by=p_actor and venue_id=v_venue;
 insert into public.vip_access_acceptances(invitation_id,version,user_id,venue_id,consent_text)
 values(v_invitation,p_version,p_actor,v_venue,v_consent) on conflict(invitation_id,version) do nothing;
 insert into public.user_terms_acceptances(user_id,version,acceptance_source,context_key,consent_text)
 values(p_actor,p_user_terms_version,'vip_activation',v_invitation::text,v_consent) on conflict(user_id,version,acceptance_source,context_key) do nothing;
 return v_venue;
end;
$function$;

revoke all on function public.record_request_terms_acceptance(uuid,text,text,text,text,text,boolean),public.record_dancer_biometric_consent(uuid,uuid,text,boolean) from public,anon,authenticated,service_role;
grant execute on function public.record_request_terms_acceptance(uuid,text,text,text,text,text,boolean),public.record_dancer_biometric_consent(uuid,uuid,text,boolean) to service_role;
create table public.account_terms_acceptances (
 user_id uuid not null references public.app_users(id) on delete cascade,
 user_terms_version text not null references public.user_terms_versions(version),
 access_terms_version text references public.vip_access_terms_versions(version),
 consent_text text not null, accepted_at timestamptz not null default clock_timestamp(),
 unique nulls not distinct(user_id,user_terms_version,access_terms_version)
);
alter table public.account_terms_acceptances enable row level security;
revoke all on public.account_terms_acceptances from public,anon,authenticated,service_role;
grant select,insert on public.account_terms_acceptances to service_role;

create function public.account_terms_access(p_user uuid,p_vip boolean default false)
returns jsonb language sql stable security invoker set search_path='' as $function$
 select jsonb_build_object('version','2026-10-30','accepted',
 exists(select 1 from public.account_terms_acceptances where user_id=p_user and user_terms_version='2026-10-30'
   and (not p_vip or access_terms_version='2026-10-30'))
 or (exists(select 1 from public.user_terms_acceptances where user_id=p_user and version='2026-10-30')
   and (not p_vip or exists(select 1 from public.vip_access_acceptances where user_id=p_user and version='2026-10-30'))));
$function$;
create function public.accept_current_account_terms(p_user uuid,p_user_version text,p_access_version text,p_accepted boolean)
returns jsonb language plpgsql security invoker set search_path='' as $function$
declare wording text;
begin
 if p_accepted is distinct from true or p_user_version is distinct from '2026-10-30'
 or (p_access_version is not null and p_access_version<>'2026-10-30')
 or not exists(select 1 from public.app_users where id=p_user and role='customer' and account_state='active') then
   raise exception 'CURRENT_USER_TERMS_REQUIRED' using errcode='22023';end if;
 select case when p_access_version is null then consent_text else vip_consent_text end into strict wording
 from public.user_terms_versions where version=p_user_version and is_current;
 insert into public.account_terms_acceptances(user_id,user_terms_version,access_terms_version,consent_text)
 values(p_user,p_user_version,p_access_version,wording) on conflict do nothing;
 return public.account_terms_access(p_user,p_access_version is not null);
end;
$function$;
revoke all on function public.account_terms_access(uuid,boolean),public.accept_current_account_terms(uuid,text,text,boolean) from public,anon,authenticated,service_role;
grant execute on function public.account_terms_access(uuid,boolean),public.accept_current_account_terms(uuid,text,text,boolean) to service_role;
notify pgrst,'reload schema';
commit;
